   array['30 minutes', '45 minutes', '60 minutes', '20 minutes'],
   'An adult football match has two halves of 45 minutes, plus stoppage time set by the referee.'),
  ('2628dfb2-3af2-51d0-80f0-e045aed5ab20', 'es',
