   array['Breaststroke', 'Sidestroke', 'Underwater swimming', 'Doggy paddle'],
   'The four official strokes are freestyle (front crawl), backstroke, breaststroke and butterfly.'),
  ('edf6f8ff-dfbf-5e27-82d0-0e78deedb2a0', 'es',
